function generateMaze(canvasId, width=500, height=500) {
  const canvas = document.getElementById(canvasId);
  const ctx = canvas.getContext('2d');
  canvas.width = width;
  canvas.height = height;

  class Cell {
    constructor(x, y) {
      this.x = x;
      this.y = y;
      this.visited = false;
      this.walls = [true, true, true, true]; // N, E, S, W
    }
  }

  const grid = Array.from({length: Math.floor((height-2)/2)}, (_, i) => (
    Array.from({length: Math.floor((width-2)/2)}, (_, j) => new Cell(2*j+1, 2*i+1))
  ));

  function draw(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x*2, y*2, 2, 2);
  }

  function carve(i, j, direction) {
    const [x1, y1] = [i, j];
    const [x2, y2] = [
      direction === 0 ? x1-2 : direction === 2 ? x1+2 : x1,  // N: x-2, S: x+2
      direction === 1 ? y1-2 : direction === 3 ? y1+2 : y1  // E: y-2, W: y+2
    ];
    const cell1 = grid[x1][y1];
    const cell2 = grid[x2][y2];
    const wallIndex = {
      0: 0, 1: 1, 2: 3, 3: 2 // N: 0, E: 1, S: 2, W: 3
    }[direction];
    cell1.walls[wallIndex] = false;
    cell2.walls[wallIndex] = false;
    draw(i*2, j*2, 'black');
  }

  function isValid(x, y) {
    return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length;
  }

  function heuristic(x1, y1, x2, y2) {
    return Math.abs(x1 - x2) + Math.abs(y1 - y2);
  }

  function reconstructPath(cameFrom, current, start, end) {
    let path = [end];
    while (current !== start) {
      current = cameFrom[current];
      path.unshift(current);
    }
    return path;
  }

  function solveMaze(x, y) {
    const start = [grid[0][0], grid[0][0]];
    grid.forEach(row => row[0].visited = true);
    const openSet = [start];
    const cameFrom = new Array(grid.length).fill().map(() => new Array(grid[0].length).fill(null));

    while (openSet.length > 0) {
      openSet.sort((a, b) => heuristic(a[0].x, a[0].y, x, y) - heuristic(b[0].x, b[0].y, x, y));
      const current = openSet.shift();
      const [i, j] = [current[0].x, current[0].y];
      draw(i, j, 'red');
      if (current[0] === grid[grid.length-1][grid[0].length-1]) {
        const path = reconstructPath(cameFrom, current[0], start[0], current[0]);
        path.forEach(([x, y]) => draw(x, y, 'blue'));
        break;
      }
      current[0].visited = true;

      for (let [xi, yi] of [[i-2, j], [i+2, j], [i, j-2], [i, j+2]]) {
        if (isValid(xi, yi) && !grid[xi][yi].visited && grid[xi][yi].walls[0] === grid[i][j].walls[2]) {
         cameFrom[xi][yi] = current;
          openSet.push([[xi, yi], heuristic(xi, yi, x, y)]);
        }
      }
    }
  }

  function drawMaze() {
    grid.forEach((row, i) => {
      row.forEach((cell, j) => {
        draw(j, i, cell.walls[0] ? 'black' : 'white');
        draw(j, i, cell.walls[1] ? 'black' : 'white');
        draw(j, i, cell.walls[2] ? 'black' : 'white');
        draw(j, i, cell.walls[3] ? 'black' : 'white');
      });
    });
    draw(0, 0, 'white');
    draw(0, 0, 'white');
    draw(grid.length-1, grid[0].length-1, 'white');
    draw(grid.length-1, grid[0].length-1, 'white');
  }

  function generate() {
    function recursiveDivision(x, y) {
      if (!isValid(x, y)) return;
      if (Math.abs(x - grid.length-1) === 0 && Math.abs(y - grid[0].length-1) === 0) return;

      if (Math.random() < 0.5) {
        carve(x, y, 0);
        recursiveDivision(x-1, y);
      }

      if (Math.random() < 0.5) {
        carve(x, y, 1);
        recursiveDivision(x, y-1);
      }
    }
    grid.forEach(row => row.forEach(cell => carve(cell.x, cell.y)));
    recursiveDivision(Math.floor(Math.random() * grid.length), Math.floor(Math.random() * grid[0].length));
  }

  generate();
  drawMaze();

  setTimeout(() => {
    solveMaze(width - 2, height - 2);
  }, 1000);
}

generateMaze('myCanvas');
